import {parts,devices,emotions,topics,sources,coreDevices} from './content.js';
import {partGuidance,exordiumExamples} from './arrangement.js';
import {speechStudies} from './studies.js';
import {emotionGuidance} from './emotion-guidance.js';
import {studyEmotions} from './study-emotions.js';
import {conclusionExamples} from './conclusions.js';
import {STORAGE_KEY,initialState,newSpeech,assembled,validateState,mergeBackup,pickDifferent,timerRemaining} from './model.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState(),saveError='',blocked=false;
try {const saved=localStorage.getItem(STORAGE_KEY);if(saved) state=validateState(JSON.parse(saved));}
catch {saveError='Saved work could not be loaded. It has not been overwritten. Export any new work before reloading.';blocked=true;}
let page='workshop',part=0,readMode=false,deviceId=devices[0].id,emotionId=emotions[0].id;
let selectedStudy=speechStudies[0].id;
const readerDrafts={};
let timer=null,deadline=0,remaining=0,phase='ready',paused=false;
const speech=()=>state.speeches.find(s=>s.id===state.selectedSpeech);
const button=(label,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function notify(message){$('#notice').textContent=message;}
function save(){
  try {if(blocked) throw Error();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));saveError='';}
  catch {saveError=blocked?saveError:'Your browser could not save this work. Export a backup now to keep it.';}
  const el=$('#save-status');if(el) el.textContent=saveError?'Not saved — export a backup':'Saved in this browser';
  const warning=$('#save-warning');if(warning) {warning.hidden=!saveError;warning.textContent=saveError;}
}
function render(){
  $('#app').innerHTML=`<aside class="rail"><a class="brand" href="#" data-action="home">Rhetoric<span>A practice room</span></a><nav aria-label="Practice areas">${[['workshop','Speech workshop','Arrange & vary'],['studies','Speech studies','Read & understand'],['devices','Device practice','Find the mechanism'],['voice','Voice practice','Practice your delivery'],['blitz','Blitz rounds','Think on your feet'],['emotions','Emotion practice','Understand the audience']].map(([id,label,sub])=>`<button data-page="${id}" ${page===id?'aria-current="page"':''}>${label}<span>${sub}</span></button>`).join('')}</nav><div class="rail-bottom">${button('Dark mode','toggle-theme','secondary theme-toggle',`aria-pressed="${document.documentElement?.dataset.theme==='dark'}"`)}<p>Practice the movement.<br>Make it your own.</p><span id="save-status">${saveError?'Not saved — export a backup':'Saved in this browser'}</span><div class="backup-actions">${button('Export backup','export')}${button('Import backup','import')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><small>Drafts stay on this device between visits.<br>Export a copy to keep it safe.</small><details class="install-help"><summary>Install on this device</summary><p>Use your browser’s Install app option. On iPhone or iPad, open in Safari and choose Share → Add to Home Screen.</p><p>Open once while connected to prepare offline practice. External source links still need internet. Clearing site data removes local drafts; there is no account or sync.</p></details></div></aside><main id="main" tabindex="-1"><div id="save-warning" class="warning" role="alert" ${saveError?'':'hidden'}>${esc(saveError)}</div>${page==='workshop'?workshop():page==='studies'?studiesPage():page==='devices'?devicePage():page==='voice'?voicePage():page==='blitz'?blitzPage():emotionPage()}</main>`;
  updateClock();
}
function heading(title,description,action='') {return `<header class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</header>`;}
function deviceOptions(){
 return devices.map(d=>`<option value="${d.id}" ${d.id===deviceId?'selected':''}>${coreDevices.has(d.id)?'★ Start here · ':''}${esc(d.title)}</option>`).join('');
}
function workshopDeviceContent(){
 const d=devices.find(item=>item.id===deviceId);
 return `<h3>${esc(d.title)}</h3><p>${esc(d.mechanism)}</p><details><summary>The name, if you’re curious</summary><p>${esc(d.id)}</p></details><h3>Hear the pattern</h3>${d.examples.map(example=>`<blockquote>${esc(example)}</blockquote>`).join('')}<p class="small muted">Original practice examples.</p><p class="reflection"><strong>Try it in your speech:</strong> Write a line using this pattern, then try a different version. ${esc(d.check)}</p>`;
}
function workshopDeviceReference(){
 return `<aside class="workshop-devices" aria-labelledby="workshop-devices-heading"><h2 id="workshop-devices-heading">Rhetorical devices</h2><label for="workshop-device-select">Choose a mechanism</label><select id="workshop-device-select">${deviceOptions()}</select><p class="small muted">★ Start here marks seven versatile patterns.</p><div id="workshop-device-content" aria-live="polite">${workshopDeviceContent()}</div></aside>`;
}
function workshop(){
 const s=speech();
 return heading('Speech workshop','One idea. Six movements. As many ways to say it as you need.',button('New speech','new-speech','primary'))+`<div class="work-layout"><aside class="library"><h2>Your speeches <span>${state.speeches.length}</span></h2>${state.speeches.length?`<div class="speech-list">${state.speeches.map(x=>`<button data-speech="${esc(x.id)}" ${x.id===state.selectedSpeech?'aria-current="true"':''}>${esc(x.title||'Untitled speech')}<span>${x.sections.filter(p=>p.variants.some(t=>t.trim())).length} of 6 parts started</span></button>`).join('')}</div>`:'<p class="muted">Your drafts will live here.</p>'}<div class="practice-note"><h3>A way to practice</h3><p>Take one speech through several variations, or write 3–5 different speeches.</p><p>Stay with it as long as you like. Then try speaking it aloud.</p></div></aside><section class="work-area">${s?editor(s):`<div class="empty"><div class="six-line" aria-hidden="true">${parts.map((_,i)=>`<i style="width:${[70,100,55,90,65,80][i]}%"></i>`).join('')}</div><h2>Give an idea a voice.</h2><p>Start with something you want someone to believe, understand, or do. We’ll give it a shape.</p>${button('Write your first speech','new-speech','primary')} ${button('Give me a topic','topic-speech','quiet')}<ol class="empty-parts">${parts.map(p=>`<li>${p[0]}</li>`).join('')}</ol></div>`}</section>${workshopDeviceReference()}</div>`;
}
function studyDevices(items=[]){
 if(!items.length)return '';
 return `<div class="study-devices"><h4>Devices to notice</h4>${items.map(device=>`<details open><summary>${esc(device.name)}</summary><blockquote>${esc(device.quote)}</blockquote><p>${esc(device.mechanism)}</p><p class="device-try"><strong>Try it:</strong> ${esc(device.tryIt)}</p></details>`).join('')}</div>`;
}
function arrangementKey(){
 return `<section class="arrangement-key" aria-labelledby="arrangement-key-title"><h3 id="arrangement-key-title">Six-part arrangement key</h3><p class="small muted">Hover for a quick explanation, or click / tap a part to keep it open. Colors indicate a reading of the passage’s role; a speech need not use all six.</p><div class="arrangement-key-items">${parts.map((p,i)=>`<details class="study-color-${i}"><summary title="${esc(p[1]+' '+p[2])}">${i+1}. ${esc(p[0])}<span>${esc(p[3])}</span></summary><p>${esc(p[1])} ${esc(p[2])}</p></details>`).join('')}</div></section>`;
}
function studyEmotionNotes(studyId,index){
 const notes=studyEmotions[studyId].filter(item=>item.section===index);
 if(!notes.length)return '';
 return `<div class="study-emotions"><h4>Emotions this passage may evoke</h4>${notes.map(item=>{const emotion=emotions.find(e=>e.id===item.emotion);return `<details open><summary>${esc(emotion.title)} · ${esc(item.effect)}</summary><p>${esc(item.mechanism)}</p><dl>${[['state','Audience’s state of mind'],['person','Whom the feeling concerns'],['cause','What provokes it']].map(([key,label])=>`<dt>${label}</dt><dd>${esc(item[key])}</dd>`).join('')}</dl><p class="small">Interpretive application of Aristotle’s framework, not a measured audience response.</p>${button('Explore '+esc(emotion.title),'','quiet',`data-page="emotions" data-emotion="${item.emotion}"`)}</details>`;}).join('')}</div>`;
}
function speechReader(study){
 if(study.mode==='guide'){
  const excerpts=study.sections.flatMap(section=>(section.devices||[]).map(device=>device.quote));
  return `<details class="speech-reader"><summary>Read excerpts or paste your own full copy</summary><p class="small muted">These are brief excerpts, not the complete speech. You can paste a copy below to read it here. Pasted text stays in this tab while you switch studies; it is cleared when you reload and is not included in backups.</p>${excerpts.map(text=>`<blockquote>${esc(text)}</blockquote>`).join('')}<label for="reader-text">Your copy of ${esc(study.title)}</label><textarea id="reader-text" class="writing" rows="18" placeholder="Paste the speech here to read it without leaving this page…">${esc(readerDrafts[study.id]||'')}</textarea></details>`;
 }
 return `<details class="speech-reader"><summary>${esc(study.readerLabel||'Read the full speech without annotations')}</summary><p class="small muted">${esc(study.edition)}</p><div class="speech-reader-text">${study.sections.map(section=>`<p>${esc(section.text)}</p>`).join('')}</div></details>${study.originalText?`<details class="speech-reader"><summary>${esc(study.originalLabel)}</summary><div class="speech-reader-text"><p>${esc(study.originalText)}</p></div></details>`:''}`;
}
function studiesPage(){
 const study=speechStudies.find(item=>item.id===selectedStudy);
 return heading('Speech studies','Follow the argument. Hear how the language works.')+`<div class="study-picker"><label for="study-select">Choose a study</label><select id="study-select">${speechStudies.map(item=>`<option value="${item.id}" ${selectedStudy===item.id?'selected':''}>${esc(item.title)} · ${esc(item.speaker)}${item.mode==='guide'?' · guided excerpts':''}</option>`).join('')}<option value="openings" ${selectedStudy==='openings'?'selected':''}>Historical opening techniques</option><option value="endings" ${selectedStudy==='endings'?'selected':''}>Historical conclusion techniques</option></select></div>${selectedStudy==='openings'?exordiumStudy():selectedStudy==='endings'?conclusionStudy():`<article class="speech-study"><header><h2>${esc(study.title)}</h2><p class="study-byline">${esc(study.speaker)} · ${esc(study.date)}</p><p>${esc(study.context)}</p><p class="small muted">${esc(study.edition)} <a href="${esc(study.source)}" target="_blank" rel="noreferrer">${study.mode==='guide'?'Read the complete speech':'Read the source'}</a></p></header>${speechReader(study)}${arrangementKey()}<nav class="study-legend" aria-label="Jump to a speech section">${study.sections.map((section,index)=>`<a class="study-color-${section.part}" href="#study-part-${index}">${index+1}. ${esc(section.title||parts[section.part][0])}</a>`).join('')}</nav><p class="study-note">${esc(study.note)}</p><p class="study-note">Emotion notes highlight selected passages and possible intended effects using Aristotle’s three questions. They are interpretations, not claims about how every listener felt.</p><div class="study-reading">${study.sections.map((section,index)=>`<section class="study-section" id="study-part-${index}" tabindex="-1" aria-labelledby="study-label-${index}"><div class="study-text study-color-${section.part}${study.mode==='guide'?' study-summary':''}"><h3 id="study-label-${index}">${index+1}. ${esc(section.title||parts[section.part][0])}<span>${study.mode==='guide'?'Summary · ':''}${esc(section.functionLabel||`Part ${section.part+1} · ${parts[section.part][0]} · ${parts[section.part][3]}`)}</span></h3><p>${esc(section.text)}</p></div><p class="study-explanation"><strong>What it does:</strong> ${esc(section.explanation)}</p>${studyDevices(section.devices)}${studyEmotionNotes(study.id,index)}</section>`).join('')}</div></article>`}`;
}
function exordiumStudy(){
 return `<section class="exordium-study"><h2>Ways to open a speech</h2><p>An exordium prepares the audience’s mind for what follows. Cicero describes its work as making listeners attentive, receptive, and well-disposed. Great openings pursue that work in different ways: accusation, gratitude, vulnerability, fairness, shared values, moral contrast, or a challenge to authority.</p><a class="small" href="${sources.arrangement}" target="_blank" rel="noreferrer">Cicero, De Inventione I.20</a><p class="small">The explanations below are readings of how each speech works, not promises of the same effect on every audience.</p><div class="historical-openings">${exordiumExamples.map(example=>`<details class="historical-opening"><summary>${esc(example.technique)}<span>${esc(example.title)} · ${esc(example.date)}</span></summary><p><strong>Primary effect:</strong> ${esc(example.effect)}</p>${example.quote?`<figure><blockquote>${esc(example.quote)}</blockquote><figcaption>${esc(example.quoteLabel)}</figcaption></figure>`:''}<p>${esc(example.context)}</p><p><strong>How it works:</strong> ${esc(example.mechanism)}</p><p><strong>Try the mechanism:</strong> ${esc(example.application)}</p>${example.note?`<p class="small">${esc(example.note)}</p>`:''}<ul class="advice-sources">${example.sources.map(([label,url])=>`<li><a href="${esc(url)}" target="_blank" rel="noreferrer">${esc(label)}</a></li>`).join('')}</ul></details>`).join('')}</div><h3>One argument. Different openings.</h3><p>Use your current speech, or try: “Technology should strengthen human relationships.” Keep the body of the argument identical. Write an opening variation for each technique above, using <strong>Add variation</strong> in the Speech workshop’s Opening section.</p><p>Read each opening into the same next paragraph. What does it lead the listener to expect, feel, or accept? Which best prepares this particular audience for your argument?</p><p class="small">Suggested study order: Pro Archia, Against Catiline, then Douglass. Compare goodwill, confrontation, and the movement between them.</p></section>`;
}
function conclusionStudy(){
 return `<section class="exordium-study"><h2>Ways to end a speech</h2><p>A conclusion brings the case together and makes its consequence felt. It can gather the reasons, call for action, return to an opening idea, or leave a clear image of the future. These examples show different choices, not a rule that every speech must end loudly.</p><p class="small">The excerpts below are actual closing passages in the identified texts, not merely famous lines from elsewhere in the speech. Explanations and drills are teaching interpretations.</p><div class="historical-openings">${conclusionExamples.map(example=>`<details class="historical-opening"><summary>${esc(example.technique)}<span>${esc(example.title)} · ${esc(example.date)}</span></summary><p><strong>Primary effect:</strong> ${esc(example.effect)}</p><figure><blockquote>${esc(example.quote)}</blockquote><figcaption>${esc(example.quoteLabel)}</figcaption></figure><p>${esc(example.context)}</p><p><strong>How it works:</strong> ${esc(example.mechanism)}</p><p><strong>Try the mechanism:</strong> ${esc(example.application)}</p>${example.note?`<p class="small">${esc(example.note)}</p>`:''}<ul class="advice-sources">${example.sources.map(([label,url])=>`<li><a href="${esc(url)}" target="_blank" rel="noreferrer">${esc(label)}</a></li>`).join('')}</ul></details>`).join('')}</div><h3>One argument. Five endings.</h3><p>Use your current speech, or argue that your town should keep its library open later. Keep the opening and body unchanged. In the workshop’s Conclusion section, use <strong>Add variation</strong> to save each ending separately.</p><ol class="delivery-steps"><li><strong>Gather the case:</strong> Bring the strongest reasons together in two sentences. End with what they establish.</li><li><strong>Ask for action:</strong> Name who should do what next and why it matters.</li><li><strong>Return to the opening:</strong> Bring back its image, question, or phrase with the meaning your argument has given it.</li><li><strong>Show the future:</strong> Give a concrete picture of what the decision makes possible. Connect it to action now.</li><li><strong>Make a quiet commitment:</strong> Say plainly what you or the audience will stand for or do. Finish without a grand flourish.</li></ol><p><strong>Test each ending aloud:</strong> Read the same final body paragraph into each variation. Pause after the last line. Can a listener tell what matters and what comes next? Does the emotion follow from the argument? Try removing the last sentence—did you already finish one sentence earlier?</p><p>Choose the ending that fits this audience. Write another version of it with fewer words, then deliver it from the idea rather than memorizing every word. Repeat as often as you like.</p>${button('Practice endings in your speech','','primary','data-page="workshop" data-workshop-part="5"')}<p class="small muted">If you have no draft yet, create a speech first, then choose Conclusion. A strong final line earns its force from what comes before it.</p></section>`;
}
function arrangementAdvice(index){
 const advice=partGuidance[index];
 return `<p class="part-aim">${esc(advice.aim)}</p><details class="part-advice"><summary>What makes this part work?</summary><ul>${advice.criteria.map(([title,text])=>`<li><strong>${esc(title)}.</strong> ${esc(text)}</li>`).join('')}</ul><p><strong>Watch out for:</strong> ${esc(advice.pitfall)}</p><p><strong>Try a variation:</strong> ${esc(advice.drill)}</p><p class="small">Practical paraphrases of classical advice, adapted from courtroom speeches. The variation drill is an original exercise; use the structure flexibly.</p><ul class="advice-sources">${advice.sources.map(([label,url])=>`<li><a href="${esc(url)}" target="_blank" rel="noreferrer">${esc(label)}</a></li>`).join('')}</ul></details>`;
}
function editor(s){
 const sec=s.sections[part];
 return `<div class="speech-heading"><label class="sr-only" for="speech-title">Speech title or topic</label><input id="speech-title" class="title-input" value="${esc(s.title)}" placeholder="Give this speech a title"><div class="toolbar">${button(readMode?'Back to writing':'Read assembled speech','read','secondary')}<label class="check"><input type="checkbox" id="hide-hints" ${state.hideHints?'checked':''}> Hide guidance</label></div></div>${readMode?`<article class="assembled"><h2>${esc(s.title||'Untitled speech')}</h2>${s.sections.map((sec,i)=>sec.variants[sec.selected].trim()?`<p>${esc(sec.variants[sec.selected])}</p>`:`<p class="missing">${parts[i][0]} is still unwritten.</p>`).join('')}<div class="toolbar">${button('Download speech','download-speech','secondary')}<span class="muted">Read it aloud. Notice where you hesitate.</span></div></article>`:`<nav class="part-tabs" aria-label="Six parts of your speech">${parts.map((p,i)=>`<button data-part="${i}" ${part===i?'aria-current="step"':''}><span>${i+1}</span>${p[0]}</button>`).join('')}</nav><div class="editor-body"><div class="part-heading"><h2>${parts[part][0]}</h2><span>${part+1} / 6</span></div>${state.hideHints?'':`<div class="guidance"><p><strong>${parts[part][1]}</strong> ${parts[part][2]}</p>${arrangementAdvice(part)}${part===0?button('Explore historical openings','', 'quiet', 'data-page="studies" data-study="openings"'):part===5?button('Explore historical endings & practice drill','', 'quiet', 'data-page="studies" data-study="endings"'):''}<details><summary>The classical term</summary><p>${parts[part][3]}. This six-part arrangement is a practice scaffold; a real speech can adapt its order and emphasis.</p><a href="${sources.arrangement}" target="_blank" rel="noreferrer">Cicero, De Inventione I.19</a></details></div>`}<div class="variation-bar"><label for="variation">Version in your speech</label><select id="variation">${sec.variants.map((_,i)=>`<option value="${i}" ${i===sec.selected?'selected':''}>Variation ${i+1}</option>`).join('')}</select>${button('Add variation','add-variation','quiet')}</div><label class="sr-only" for="speech-text">${parts[part][0]}, variation ${sec.selected+1}</label><textarea id="speech-text" class="writing" placeholder="Try it in your own words…">${esc(sec.variants[sec.selected])}</textarea><div class="editor-footer"><span id="word-count">${words(sec.variants[sec.selected])} words</span>${button(part<5?'Next part':'Read your speech',part<5?'next-part':'read','secondary')}</div>${state.hideHints?'':`<p class="small muted">Try a different opening move, a different image, or a different rhythm. Each variation is saved separately.</p>`}</div>`}`;
}
function words(t){return t.trim()?t.trim().split(/\s+/u).length:0;}
function deviceSubject(refresh=false){
 const draft=state.deviceDrafts[deviceId]||={};
 if(refresh||!draft.topic){draft.topic=pickDifferent(topics,draft.topic||'');save();}
}
function devicePage(){
 const d=devices.find(x=>x.id===deviceId);
 return heading('Device practice','Learn what a pattern does. Then make it do something of your own.',button('Another device','random-device','secondary'))+`<div class="lesson-layout"><aside class="lesson-list"><label for="device-select">Choose a mechanism</label><select id="device-select">${deviceOptions()}</select><p class="muted">31 ways to shape a thought.</p><p class="small">★ Start here: seven versatile patterns for strong everyday speaking and writing. Impact depends on the audience and purpose, not a fixed ranking.</p><p class="small">You don’t need the name to use the movement.</p><a class="small" href="${sources.devices}" target="_blank" rel="noreferrer">Starting list · Merriam-Webster</a></aside><article class="lesson"><h2>${d.title}</h2><p class="lead">${d.mechanism}</p><details><summary>The name, if you’re curious</summary><p>${esc(d.id)}</p></details><div class="examples"><h3>Hear the pattern</h3>${d.examples.map(e=>`<blockquote>${esc(e)}</blockquote>`).join('')}<p class="small muted">Original practice examples.</p></div><h3>Try the movement</h3><p>Write two or three lines about this subject using the pattern above. Try several versions, then say each aloud.</p><div class="connection"><h3>Your practice subject</h3><p id="device-subject" aria-live="polite">${esc(state.deviceDrafts[d.id]?.topic||'')}</p>${button('Another subject','random-device-topic','secondary')}</div><details><summary>Another way to practice</summary><p>${esc(d.prompt)}</p></details>${speech()?`<p class="connection">Or apply it to <strong>${esc(speech().title||'your current speech')}</strong>. Try a line you could use in its ${parts[part][0].toLowerCase()}.</p>`:''}<label for="device-text">Your attempts</label><textarea id="device-text" class="writing" placeholder="Write a few versions. Say each one aloud.">${esc(state.deviceDrafts[d.id]?.text||'')}</textarea><p class="reflection"><strong>Listen back to yourself:</strong> ${d.check}</p></article></div>`;
}
function voicePage(){
 const source='https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Quintilian/Institutio_Oratoria/11C%2A.html';
 const drills=[
  ['Know the words. Attend to the voice.','§25','Quintilian recommends familiar passages with varied kinds of delivery, so inventing words does not distract from vocal practice.','Learn a few short passages well enough to speak without searching for words. Choose contrasting material: a conversation, an argument, an urgent appeal, and a gentle reassurance. Rehearse each in a fitting voice.','Can you attend to your listener instead of trying to remember the next word?'],
  ['Rehearse a real speech','§29','He recommends daily speaking practice that resembles the actual task of addressing an audience.','Deliver one of your speeches aloud. Picture a particular listener and what you want them to understand or do. Finish the argument, then repeat any passage that felt awkward.','Does the delivery help your argument reach that listener?'],
  ['Make the thought easy to hear','§§33–39','He calls for complete, clear words and pauses that make the meaning intelligible, without exaggerated pronunciation.','Read a paragraph slowly enough to finish each word naturally. Mark a slash at a short pause and a double slash at the end of a complete thought. Read again, letting the meaning guide the pauses.','Could someone hearing it once follow where each thought begins and ends?'],
  ['Give important words their weight','§§43–51','He asks for variety of tone and emphasis suited to the meaning, rather than monotonous delivery.','Say “We can still change this” three times. First emphasize “we,” then “still,” then “change.” Notice how the implied message shifts. Choose the emphasis that suits your audience, then try this with a line of your own.','What changes in meaning when a different word carries the weight?'],
  ['Breathe with the sense','§§52–54','He advises against both breaking sentences with too many breaths and speaking until the breath is exhausted.','Take a short paragraph and find natural places to breathe between thoughts. Speak at a comfortable pace, breathing where needed. Adjust your phrasing if you keep running out of breath.','Can you finish each phrase comfortably without rushing its last words?']
 ];
 return heading('Voice practice','Keep the words. Change the intention. Hear what your delivery can do.')+`<article class="lesson voice-practice"><h2>One passage. Four deliveries.</h2><p class="lead">Choose a short passage from your own speech or a speech study. Keep its words identical through each delivery.</p><ol class="delivery-steps"><li>Say it conversationally, as if explaining it to a friend.</li><li>Repeat it to persuade a skeptical listener.</li><li>Repeat it to encourage someone who feels defeated.</li><li>Deliver it again with the intention that best fits its meaning.</li></ol><p class="reflection"><strong>Notice:</strong> What changed in your pauses, emphasis, pace, and tone? Now improvise your own paragraph with the same intention.</p><p>Repeat with any passage, as often as you like. There is no timer, recording, or score.</p><div class="toolbar">${button('Choose a speech study','','secondary','data-page="studies"')}${button('Use your own speech','','secondary','data-page="workshop"')}</div><h3>Focus on one skill</h3><p>These exercises and the routine above are modern adaptations of Quintilian’s advice, not routines quoted from his book.</p><div class="voice-drills">${drills.map(([title,section,principle,exercise,reflection])=>`<details class="part-advice"><summary>${esc(title)}</summary><p><strong>Quintilian’s advice:</strong> ${esc(principle)}</p><p><strong>Try it:</strong> ${esc(exercise)}</p><p><strong>Listen for:</strong> ${esc(reflection)}</p><a href="${source}" target="_blank" rel="noreferrer">Institutio Oratoria XI.3, ${section}</a></details>`).join('')}</div><p class="small muted">Keep the voice comfortable; do not force volume or continue through strain. This is practice in delivery, not a breath-holding contest.</p></article>`;
}
function emotionOutline(id){
 const g=emotionGuidance[id];
 return `<details class="part-advice emotion-outline" open><summary>Aristotle’s account</summary><p class="small muted">Plain-language paraphrase of Rhetoric II.${g.chapter}. These are Aristotle’s observations and assumptions, not universal rules of psychology.</p><p><strong>What it is:</strong> ${esc(g.definition)}</p><dl>${[['state','State of mind'],['person','People involved'],['cause','What brings it about']].map(([key,label])=>`<dt>${label}</dt><dd>${esc(g[key])}</dd>`).join('')}</dl><p><strong>Key distinction:</strong> ${esc(g.distinction)}</p><a href="${sources.emotions}" target="_blank" rel="noreferrer">Read Rhetoric, Book II, Part ${g.chapter} · W. Rhys Roberts translation</a></details>`;
}
function emotionPage(){
 const e=emotions.find(x=>x.id===emotionId),draft=state.emotionDrafts[e.id]||{};
 return heading('Emotion practice','Understand the audience before you choose the words.')+`<div class="lesson-layout"><aside class="lesson-list"><label for="emotion-select">Explore an emotion</label><select id="emotion-select">${emotions.map(e=>`<option value="${e.id}" ${e.id===emotionId?'selected':''}>${e.title}</option>`).join('')}</select><p class="small muted">A compact study of Aristotle’s account, not a promise that every audience responds alike.</p><a class="small" href="${sources.emotions}" target="_blank" rel="noreferrer">Read Rhetoric · Book II</a></aside><article class="lesson"><h2>${e.title}</h2>${emotionOutline(e.id)}<h3>Apply it to an audience</h3><p class="lead">${e.scenario}</p><p>Picture a particular audience. Work through all three questions before writing your passage.</p><div class="emotion-fields">${[['state','What state of mind are they in?',e.state],['person','Whom does the feeling concern?',e.person],['cause','What could provoke the feeling?',e.cause]].map(([key,label,hint],i)=>`<label for="emotion-${key}"><span>${i+1}. ${label}</span><small>Aristotle’s lens: ${hint.toLowerCase()}.</small><textarea id="emotion-${key}" data-emotion-field="${key}" rows="3" placeholder="Apply this to the situation…">${esc(draft[key]||'')}</textarea></label>`).join('')}</div><h3>Put your understanding into words</h3><p>Write a short passage to evoke or calm this feeling. Use the audience, relationship, and circumstances you identified.</p><label class="sr-only" for="emotion-passage">Your emotional appeal</label><textarea id="emotion-passage" data-emotion-field="passage" class="writing" placeholder="What would you say to this audience?">${esc(draft.passage||'')}</textarea><p class="reflection">Read it aloud. Which specific words change how the audience might see the situation?</p></article></div>`;
}
function blitzPage(){
 const b=state.blitz,d=devices.find(d=>d.id===b.device);
 return heading('Blitz rounds','A fresh subject. A little preparation. Then find your way aloud.',button('New round','new-round','primary'))+`<div class="blitz-layout"><section class="blitz-main"><label for="blitz-topic">Your speaking prompt</label><textarea id="blitz-topic" class="topic-input" rows="3">${esc(b.topic)}</textarea><div class="device-cue"><h2>Try this movement</h2><h3>${d.title}</h3><p>${d.mechanism}</p><blockquote>${esc(d.examples[0])}</blockquote></div><div class="timer-panel"><label class="check"><input id="timed" type="checkbox" ${b.timed?'checked':''}> Use a timer</label>${b.timed?`<div class="timer-settings"><label for="prep">Prepare <input id="prep" type="number" min="1" max="3600" value="${b.prep}" ${phase!=='ready'?'disabled':''}> seconds</label><label for="speak">Speak <input id="speak" type="number" min="1" max="3600" value="${b.speak}" ${phase!=='ready'?'disabled':''}> seconds</label></div><div class="clock" id="clock" aria-label="Time remaining"></div>`:''}<p id="phase-status" role="status"></p><div class="toolbar">${button(phase==='ready'?'Begin round':phase==='prepare'?'Start speaking':phase==='speak'?'Finish round':'Practice again','advance','primary')}${b.timed&&['prepare','speak'].includes(phase)?button(paused?'Resume':'Pause','pause','secondary'):''}</div></div><label for="blitz-notes">Notes to carry into the next round</label><textarea id="blitz-notes" rows="5" placeholder="Where did you find your rhythm? What would you try differently?">${esc(b.notes)}</textarea></section><aside class="blitz-guide"><h2>Your six movements</h2><ol>${parts.map(p=>`<li><strong>${p[0]}</strong><span>${p[1]}</span></li>`).join('')}</ol><p class="small muted">Speak aloud wherever you are. Nothing is recorded. Finish when you’re ready.</p></aside></div>`;
}
function updateClock(){const c=$('#clock');if(c){const t=phase==='ready'?state.blitz.prep:remaining;c.textContent=`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;}const status=$('#phase-status');if(status) status.textContent=({ready:'Ready when you are.',prepare:'Prepare your route through the argument.',speak:'Speak aloud. Keep moving through the six parts.',done:'Round complete. Take a breath and reflect.'}[phase])+(paused?' Timer paused.':'');}
function stopTimer(){clearInterval(timer);timer=null;}
function startPhase(next){stopTimer();phase=next;paused=false;remaining=next==='prepare'?state.blitz.prep:next==='speak'?state.blitz.speak:0;if(state.blitz.timed&&['prepare','speak'].includes(next))runTimer();render();}
function runTimer(){deadline=Date.now()+remaining*1000;timer=setInterval(()=>{remaining=timerRemaining(deadline);updateClock();if(!remaining){if(phase==='prepare')startPhase('speak');else startPhase('done');}},200);}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function createSpeech(topic){const s=newSpeech(topic);state.speeches.unshift(s);state.selectedSpeech=s.id;part=0;readMode=false;save();render();$('#speech-title').focus();$('#speech-title').select();}
document.addEventListener('click',e=>{
 const target=e.target.closest('button,a[data-action]');if(!target)return;
 if(target.dataset.page){page=target.dataset.page;if(target.dataset.study)selectedStudy=target.dataset.study;if(target.dataset.emotion)emotionId=target.dataset.emotion;if(page==='devices')deviceSubject();if(target.dataset.workshopPart){part=Number(target.dataset.workshopPart);readMode=false;}render();$('#main').focus();return;}
 if(target.dataset.speech){state.selectedSpeech=target.dataset.speech;readMode=false;save();render();return;}
 if(target.dataset.part!==undefined){part=Number(target.dataset.part);render();return;}
 const a=target.dataset.action;
 if(a==='home'){e.preventDefault();page='workshop';render();}
 else if(a==='new-speech')createSpeech();
 else if(a==='topic-speech')createSpeech(pickDifferent(topics,''));
 else if(a==='read'){readMode=!readMode;render();}
 else if(a==='next-part'){part++;render();$('#speech-text').focus();}
 else if(a==='add-variation'){const sec=speech().sections[part];sec.variants.push('');sec.selected=sec.variants.length-1;save();render();$('#speech-text').focus();}
 else if(a==='export'){download('rhetoric-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));notify('Backup exported. Keep it somewhere safe.');}
 else if(a==='import')$('#import-file').click();
 else if(a==='download-speech')download('speech.txt',speech().title+'\n\n'+assembled(speech()),'text/plain');
 else if(a==='random-device'){deviceId=pickDifferent(devices.map(d=>d.id),deviceId);deviceSubject();render();}
 else if(a==='random-device-topic'){deviceSubject(true);render();}
 else if(a==='new-round'){stopTimer();phase='ready';paused=false;state.blitz.topic=pickDifferent(topics,state.blitz.topic);state.blitz.device=pickDifferent(devices.map(d=>d.id),state.blitz.device);save();render();notify('New prompt ready. Your reflection notes are kept.');}
 else if(a==='advance')startPhase(phase==='ready'?'prepare':phase==='prepare'?'speak':phase==='speak'?'done':'prepare');
 else if(a==='pause'){if(paused){paused=false;runTimer();}else{remaining=timerRemaining(deadline);paused=true;stopTimer();}render();}
});
document.addEventListener('input',e=>{
 const t=e.target;
 if(t.id==='reader-text'){readerDrafts[selectedStudy]=t.value;return;}
 if(t.id==='speech-title'){speech().title=t.value;const item=document.querySelector(`[data-speech="${CSS.escape(state.selectedSpeech)}"]`);if(item)item.firstChild.textContent=t.value||'Untitled speech';}
 else if(t.id==='speech-text'){const s=speech().sections[part];s.variants[s.selected]=t.value;$('#word-count').textContent=words(t.value)+' words';}
 else if(t.id==='device-text'){state.deviceDrafts[deviceId]={...state.deviceDrafts[deviceId],text:t.value};}
 else if(t.dataset.emotionField){state.emotionDrafts[emotionId]||={};state.emotionDrafts[emotionId][t.dataset.emotionField]=t.value;}
 else if(t.id==='blitz-topic')state.blitz.topic=t.value;
 else if(t.id==='blitz-notes')state.blitz.notes=t.value;
 else return;
 save();
});
document.addEventListener('change',async e=>{
 const t=e.target;
 if(t.id==='workshop-device-select'){deviceId=t.value;$('#workshop-device-content').innerHTML=workshopDeviceContent();return;}
 if(t.id==='study-select'){selectedStudy=t.value;render();return;}
 else if(t.id==='hide-hints')state.hideHints=t.checked;
 else if(t.id==='variation')speech().sections[part].selected=Number(t.value);
 else if(t.id==='device-select'){deviceId=t.value;deviceSubject();}
 else if(t.id==='emotion-select')emotionId=t.value;
 else if(t.id==='timed'){state.blitz.timed=t.checked;stopTimer();phase='ready';paused=false;}
 else if(['prep','speak'].includes(t.id)){if(!t.validity.valid||!Number.isInteger(Number(t.value))){t.value=state.blitz[t.id];notify('Choose a whole number from 1 to 3600 seconds.');return;}state.blitz[t.id]=Number(t.value);}
 else if(t.id==='import-file'){
   const file=t.files[0];if(!file)return;
   try{if(file.size>10*1024*1024)throw Error('This file is too large. Import a backup smaller than 10 MB.');const incoming=validateState(JSON.parse(await file.text()));state=mergeBackup(state,incoming);save();render();notify('Backup imported. Your existing work has been kept.');}
   catch(error){notify(error instanceof SyntaxError?'This file is not valid JSON. Choose an exported Rhetoric backup.':error.message);t.value='';}return;
 }else return;
 save();render();
});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){blocked=true;saveError='Work changed in another tab. Export this tab’s work, then reload to load the other changes.';save();}});
render();
